SCALE=10**30

def down(x):return F(x.numerator*SCALE//x.denominator,SCALE)

def up(x):return -down(-x)

def atan_bounds(q,n=60):
 lo=sum((F((-1)**j,(2*j+1)*q**(2*j+1)) for j in range(n)),F(0))
 return lo,lo+F(1,(2*n+1)*q**(2*n+1))

def sqrts(x):
 k=isqrt(x.numerator*SCALE*SCALE//x.denominator)
 return F(k,SCALE),F(k+1,SCALE)

def exp_bounds(u):
 assert u>=0
 k=0
 while u>1:u/=2;k+=1
 term=F(1);s=term
 for j in range(1,27):
  term*=-u/j;s+=term
 lo=down(s-term*u/27);hi=up(s)
 for j in range(k):lo=down(lo*lo);hi=up(hi*hi)
 return lo,hi

@lru_cache(None)
def gaussian_tail_bounds(x):
    """Exact rational enclosure of I(x)=integral_x^infty exp(-r*r) dr."""
    x=F(x)
    assert x>=0
    if x==0:return NULO,NUHI
    # Alternating series, truncated after an even index well inside its
    # decreasing tail. Exact Fraction evaluation avoids cancellation losses.
    n=max(30,4*((x*x).numerator//(x*x).denominator+1)+80)
    n+=n%2
    term=x;total=term
    # term_j = (-1)^j*x^(2j+1)/j!, integral denominator is 2j+1.
    for j in range(1,n+1):
        term*=-x*x/j
        total+=term/(2*j+1)
    next_abs=term*x*x/(n+1)/(2*n+3)
    assert term>0
    assert x*x<n+1
    return max(F(0),down(NULO-total)),up(NUHI-total+next_abs)

def I(x):return (F(x),F(x))

def add(a,b):return down(a[0]+b[0]),up(a[1]+b[1])

def neg(a):return -a[1],-a[0]

def sub(a,b):return add(a,neg(b))

def mul(a,b):
 z=[x*y for x in a for y in b];return down(min(z)),up(max(z))

def inv(a):
 assert a[0]>0,a
 return down(1/a[1]),up(1/a[0])

def div(a,b):return mul(a,inv(b))

def sc(c,a):return mul(I(c),a)

def sq(a):return tuple(map(lambda x:x,square_bounds(a)))

def fhi(x):
    y=float(x)
    if F.from_float(y)<x:y=math.nextafter(y,math.inf)
    return y

def flo(x):
    y=float(x)
    if F.from_float(y)>x:y=math.nextafter(y,-math.inf)
    return y

@lru_cache(None)
def cos_bounds(q):
    q=abs(F(q));assert q<=F(1,2)
    if q==0:return F(1),F(1)
    if q==F(1,2):return F(0),F(0)
    x=q*(PILO+PIHI)/2
    term=F(1);total=term
    for j in range(1,19):
        term*=-x*x/((2*j-1)*(2*j));total+=term
    # Last index even, next negative; cos is 1-Lipschitz.
    error=term*x*x/(37*38)+q*(PIHI-PILO)/2
    return max(F(0),down(total-error)),min(F(1),up(total+q*(PIHI-PILO)/2))

a,b=atan_bounds(5); c,d=atan_bounds(239)

a,b=atan_bounds(5); c,d=atan_bounds(239)

PILO,PIHI=16*a-4*d,16*b-4*c

NULO=sqrts(PILO)[0]/2; NUHI=sqrts(PIHI)[1]/2

NULO=sqrts(PILO)[0]/2; NUHI=sqrts(PIHI)[1]/2

PILO=down(PILO);PIHI=up(PIHI)

PILO=down(PILO);PIHI=up(PIHI)

def rational(x):
    """Strings/Fractions denote rationals; float values denote exact dyadics."""
    if isinstance(x,float):return F.from_float(x)
    return F(x)

@lru_cache(None)
def trig_pi(q,kind):
    """Enclose sin(pi*q) or cos(pi*q), for any rational q."""
    q=F(q)%2
    if kind=='sin':return trig_pi(F(1,2)-q,'cos')
    if kind!='cos':raise ValueError('kind must be cos or sin')
    if q>1:q=2-q
    sign=1
    if q>F(1,2):q=1-q;sign=-1
    lo,hi=cos_bounds(q)
    return (lo,hi) if sign==1 else (-hi,-lo)

@lru_cache(None)
def radial_tails(r,max_degree=6):
    """J_k(r)=integral_r^infinity 2*s^(k+1)*exp(-s*s) ds."""
    r=F(r);assert r>=0 and max_degree>=0
    er=exp_bounds(r*r);out=[er]
    if max_degree:
        out.append(add(sc(r,er),gaussian_tail_bounds(r)))
    for k in range(2,max_degree+1):
        out.append(add(sc(r**k,er),sc(F(k,2),out[k-2])))
    return tuple(out)

def angular_cell(qlo,qhi,max_harmonic=4):
    """Angles are pi*qlo, pi*qhi; the measure is dtheta/(2*pi)."""
    qlo,qhi=F(qlo),F(qhi);assert qlo<qhi and max_harmonic>=0
    C=[I((qhi-qlo)/2)];S=[I(0)]
    for m in range(1,max_harmonic+1):
        denominator=sc(2*m,(PILO,PIHI))
        C.append(div(sub(trig_pi(m*qhi,'sin'),trig_pi(m*qlo,'sin')),denominator))
        S.append(div(sub(trig_pi(m*qlo,'cos'),trig_pi(m*qhi,'cos')),denominator))
    return tuple(C),tuple(S)

def generate(step=F('.02'),ntheta=128,R=F(8),radial_nodes=None,max_degree=6,max_harmonic=4):
    """Return exact factor intervals; radial includes one final tail row."""
    step,R=rational(step),rational(R)
    assert step>0 and R>0 and isinstance(ntheta,int) and ntheta>0
    if radial_nodes is None:
        nodes=[F(0)]
        while nodes[-1]<R:nodes.append(min(R,nodes[-1]+step))
    else:
        nodes=[rational(x) for x in radial_nodes]
        assert nodes[0]==0 and nodes[-1]==R and all(a<b for a,b in zip(nodes,nodes[1:]))
    tails=[radial_tails(r,max_degree) for r in nodes]
    radial=[]
    for a,b in zip(tails,tails[1:]):
        row=[]
        for x,y in zip(a,b):
            lo,hi=sub(x,y);assert hi>=0
            row.append((max(F(0),lo),hi))
        radial.append(tuple(row))
    radial.append(tails[-1])
    edges=[F(2*j,ntheta) for j in range(ntheta+1)]
    C=[];S=[]
    for a,b in zip(edges,edges[1:]):
        c,s=angular_cell(a,b,max_harmonic);C.append(c);S.append(s)
    invsqrt2=inv(sqrts(F(2)))
    data={'version':1,'radial_nodes':nodes,'angular_edges_pi':edges,
          'max_degree':max_degree,'max_harmonic':max_harmonic,
          'radial':radial,'cosine':C,'sine':S,'invsqrt2':invsqrt2,
          'pi':(PILO,PIHI),'tail_row':len(radial)-1}
    validate_normalization(data)
    return data

def validate_normalization(data):
    def total(intervals):
        intervals=list(intervals)
        return sum((p[0] for p in intervals),F(0)),sum((p[1] for p in intervals),F(0))
    def contains(interval,lower,upper=None):
        upper=lower if upper is None else upper
        assert interval[0]<=lower<=upper<=interval[1],(interval,lower,upper)
    for k in range(data['max_degree']+1):
        val=total(row[k] for row in data['radial'])
        if k%2==0:contains(val,F(factorial(k//2)))
        else:
            # Gamma(1+k/2) = (1*3*...*k)/2^((k-1)/2) * sqrt(pi)/2.
            coeff=F(math.prod(range(1,k+1,2)),2**((k-1)//2))
            contains(val,coeff*NULO,coeff*NUHI)
    for m in range(data['max_harmonic']+1):
        contains(total(row[m] for row in data['cosine']),F(1 if m==0 else 0))
        contains(total(row[m] for row in data['sine']),F(0))
    return True

def interval_hex(interval):return flo(interval[0]).hex(),fhi(interval[1]).hex()

