SCALE=10**30

def down(x): return F(x.numerator*SCALE//x.denominator,SCALE)

def up(x): return -down(-x)

def pt(x): return (F(x),F(x))

def add(a,b): return down(a[0]+b[0]),up(a[1]+b[1])

def neg(a): return -a[1],-a[0]

def sub(a,b): return add(a,neg(b))

def mul(a,b):
    v=[x*y for x in a for y in b]
    return down(min(v)),up(max(v))

def inv(a):
    assert a[0]>0 or a[1]<0, ('Interval crosses zero',a)
    return down(1/a[1]),up(1/a[0])

def div(a,b): return mul(a,inv(b))

def sq(a):
    lo=F(0) if a[0]<=0<=a[1] else min(a[0]**2,a[1]**2)
    return down(lo),up(max(a[0]**2,a[1]**2))

def dot(a,b):
    s=pt(0)
    for x,y in zip(a,b): s=add(s,mul(x,y))
    return s

def fromhex(x):
    v=tuple(F.from_float(float.fromhex(y)) for y in x)
    assert v[0]<=v[1]
    return v

def inverse_exact(a):
    n=len(a);r=[list(row)+[F(i==j) for j in range(n)] for i,row in enumerate(a)]
    for i in range(n):
        k=next(k for k in range(i,n) if r[k][i])
        r[i],r[k]=r[k],r[i]
        d=r[i][i];r[i]=[x/d for x in r[i]]
        for j in range(n):
            if j!=i:
                d=r[j][i];r[j]=[x-d*y for x,y in zip(r[j],r[i])]
    return [row[n:] for row in r]

def ldl(a):
    n=len(a);L=[[pt(i==j) for j in range(n)] for i in range(n)];D=[]
    for i in range(n):
        d=a[i][i]
        for k in range(i):d=sub(d,mul(sq(L[i][k]),D[k]))
        assert d[0]>0, ('Free Schur matrix not certified positive',i,d)
        D.append(d)
        for j in range(i+1,n):
            v=a[j][i]
            for k in range(i):v=sub(v,mul(mul(L[j][k],L[i][k]),D[k]))
            L[j][i]=div(v,d)
    return L,D

def solve_ldl(L,D,b):
    n=len(b);z=[]
    for i in range(n):
        v=b[i]
        for k in range(i):v=sub(v,mul(L[i][k],z[k]))
        z.append(v)
    y=[div(v,d) for v,d in zip(z,D)];x=[pt(0)]*n
    for i in reversed(range(n)):
        v=y[i]
        for k in range(i+1,n):v=sub(v,mul(L[k][i],x[k]))
        x[i]=v
    return x

def block_matrix(profile):
    eps=F(profile['epsilon']);M=[[F(0) for _ in range(12)] for _ in range(12)]
    E,R,I=([[F(x) for x in row] for row in profile[key]] for key in ['M_E','M_R','M_I'])
    for start,block in [(0,E),(3,E),(6,R),(8,I),(10,[[eps,0],[0,eps]])]:
        for i,row in enumerate(block):
            for j,x in enumerate(row):M[start+i][start+j]=F(x)
    return M

