import heapq,json

def reduce_residual(profile,moments):
    M=block_matrix(profile);Mi=inverse_exact(M)
    G=[[fromhex(v) for v in row] for row in moments['G']]
    b=[fromhex(v) for v in moments['b']];c=fromhex(moments['c'])
    assert len(G)==len(b)==12 and all(len(row)==12 for row in G)
    D=[[sub(pt(Mi[i][j]),G[i][j]) for j in range(12)] for i in range(12)]
    for i in range(12):
        for j in range(i):
            v=max(D[i][j][0],D[j][i][0]),min(D[i][j][1],D[j][i][1])
            assert v[0]<=v[1];D[i][j]=D[j][i]=v
    L,pivots=ldl(D)
    g=[G[i][0] for i in range(12)]
    ib=solve_ldl(L,pivots,b);ig=solve_ldl(L,pivots,g)
    c0=add(c,dot(b,ib))
    c0=add(c0,pt(2*F(profile['beta'])**2/F(profile['epsilon'])))
    c1=mul(pt(2),add(b[0],dot(g,ib)))
    c2=add(G[0][0],dot(g,ig))
    return {'coefficient_intervals':[[str(x) for x in y] for y in (c0,c1,c2)],
            'upper_coefficients':[str(x[1]) for x in (c0,c1,c2)],
            'positive_pivot_lower_bounds':[str(v[0]) for v in pivots]}

from fractions import Fraction as F

from math import comb

def value(p,x):
    out=F(0)
    for a in reversed(p):out=out*x+F(a)
    return out

def shifted(p,L,H=None):
    p=list(map(F,p));L=F(L);scale=F(1) if H is None else F(H)-L
    assert scale>=0
    return [sum((p[k]*comb(k,j)*L**(k-j)*scale**j for k in range(j,len(p))),F(0)) for j in range(len(p))]

def bernstein(p,L,H):
    power=shifted(p,L,H);n=len(power)-1
    return [sum((power[j]*F(comb(i,j),comb(n,j)) for j in range(i+1)),F(0)) for i in range(n+1)]

def difference(p,q):
    a=list(map(F,p));a.extend([F(0)]*max(0,len(q)-len(a)))
    for i,v in enumerate(q):a[i]-=F(v)
    return a

def exact_positive_definite(matrix,label,strict=True):
    """Exact LDL for positive definiteness, or semidefiniteness if requested.

    A zero Schur diagonal in a positive semidefinite matrix forces the
    corresponding remaining row and column to vanish; this is checked exactly.
    """
    n=len(matrix)
    assert all(len(row)==n for row in matrix)
    assert all(matrix[i][j]==matrix[j][i] for i in range(n) for j in range(n))
    L=[[F(i==j) for j in range(n)] for i in range(n)];D=[]
    for i in range(n):
        d=matrix[i][i]-sum((L[i][k]**2*D[k] for k in range(i)),F(0))
        assert d>0 if strict else d>=0,(label,i,d)
        D.append(d)
        for j in range(i+1,n):
            residual=matrix[j][i]-sum((L[j][k]*L[i][k]*D[k] for k in range(i)),F(0))
            if d:
                L[j][i]=residual/d
            else:
                assert residual==0,(label,'nonzero column at zero pivot',i,j,residual)
                L[j][i]=F(0)
    return D

from collections import Counter

from fractions import Fraction as F

def multiply(a, b):
    out = [F(0)] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            out[i + j] += x * y
    return out

CPP_RESIDUAL = '// Outward-rounded assembly for the finite-fiber tangent certificate.\n// Compile: g++ -O2 -std=c++17 -fno-fast-math -ffp-contract=off residual_kernel.cpp -o residual_kernel\n// Input is generated and output is parsed by the accompanying Python verifier.\n#include <algorithm>\n#include <array>\n#include <cfenv>\n#include <cfloat>\n#include <cstdint>\n#include <cstring>\n#include <cmath>\n#include <complex>\n#include <cstdlib>\n#include <iomanip>\n#include <iostream>\n#include <limits>\n#include <sstream>\n#include <stdexcept>\n#include <string>\n#include <vector>\n#if defined(__FAST_MATH__)\n#error "The interval certificate must not be compiled with fast-math."\n#endif\nstatic_assert(FLT_EVAL_METHOD == 0,"Binary64 without excess precision is required.");\nstatic_assert(std::numeric_limits<double>::is_iec559 &&\n              std::numeric_limits<double>::radix == 2 &&\n              std::numeric_limits<double>::digits == 53 &&\n              std::numeric_limits<double>::max_exponent == 1024 &&\n              std::numeric_limits<double>::min_exponent == -1021 &&\n              std::numeric_limits<double>::has_denorm == std::denorm_present &&\n              sizeof(double) == sizeof(std::uint64_t),\n              "IEEE754 binary64 with gradual underflow is required.");\nstatic std::uint64_t bits(double x){std::uint64_t b;std::memcpy(&b,&x,sizeof b);return b;}\nstatic void platform_guard(){\n if(std::fesetround(FE_TONEAREST)!=0 || std::fegetround()!=FE_TONEAREST)\n  throw std::runtime_error("Cannot establish round-to-nearest.");\n // Volatile arithmetic tests both production and consumption of subnormals,\n // detecting FTZ/DAZ modes that the type traits do not detect.\n volatile double tiny=std::numeric_limits<double>::denorm_min();\n volatile double normal=std::numeric_limits<double>::min();\n volatile double scale=0x1p-52;\n volatile double produced=normal*scale;\n volatile double consumed=produced+produced;\n if(bits(tiny)!=1 || bits(produced)!=1 || bits(consumed)!=2)\n  throw std::runtime_error("Gradual subnormal production and consumption are required.");\n volatile double one=1.0,half_ulp=0x1p-53;\n volatile double even_tie=one+half_ulp;\n volatile double odd=0x1.0000000000001p0;\n volatile double odd_tie=odd+half_ulp;\n if(bits(even_tie)!=bits(1.0) || bits(odd_tie)!=bits(0x1.0000000000002p0))\n  throw std::runtime_error("Round-to-nearest with ties to even is required.");\n}\nstruct I {double lo,hi;};\nstatic const double inf=std::numeric_limits<double>::infinity();\ninline double dn(double x){return std::nextafter(x,-inf);}\ninline double up(double x){return std::nextafter(x,inf);}\ninline I exact(double x){return {x,x};}\ninline I add(I a,I b){return {dn(a.lo+b.lo),up(a.hi+b.hi)};}\ninline I neg(I a){return {-a.hi,-a.lo};}\ninline I sub(I a,I b){return add(a,neg(b));}\ninline I mul(I a,I b){\n double p[4]={a.lo*b.lo,a.lo*b.hi,a.hi*b.lo,a.hi*b.hi};\n return {dn(*std::min_element(p,p+4)),up(*std::max_element(p,p+4))};\n}\ninline I recip_positive(I a){if(!(a.lo>0))throw std::runtime_error("nonpositive reciprocal argument");return {dn(1/a.hi),up(1/a.lo)};}\ninline void accum(I &a,I b){a=add(a,b);}\ninline double read_double(){std::string s;if(!(std::cin>>s))throw std::runtime_error("missing input");char *end=nullptr;double x=std::strtod(s.c_str(),&end);if(!end||*end||!std::isfinite(x))throw std::runtime_error("invalid finite float");return x;}\ninline I read_I(){I a{read_double(),read_double()};if(a.lo>a.hi)throw std::runtime_error("inverted interval");return a;}\nstd::string hex(double x){if(!std::isfinite(x))throw std::runtime_error("nonfinite output");std::ostringstream s;s<<std::hexfloat<<x;return s.str();}\nvoid print_I(I a){std::cout<<"[\\""<<hex(a.lo)<<"\\",\\""<<hex(a.hi)<<"\\"]";}\nusing Angular=std::array<std::array<I,2>,5>; // frequency, cos/sin\nusing Moments=std::array<std::array<std::array<I,2>,5>,7>; // radial degree, frequency, cos/sin\nstruct Coeff{I re,im;};\nstruct Term{int k,m;Coeff c;};\nusing Poly=std::vector<Term>;\nCoeff realcoef(I x){return {x,exact(0)};}\nCoeff imagcoef(I x){return {exact(0),x};}\nCoeff conjugate_product(Coeff a,Coeff b){return {add(mul(a.re,b.re),mul(a.im,b.im)),sub(mul(a.re,b.im),mul(a.im,b.re))};}\nI moment(const Moments& a,int k,int m,int which){if(k<0||k>6||std::abs(m)>4)throw std::runtime_error("moment outside certified range");I v=a[k][std::abs(m)][which];return (m<0&&which==1)?neg(v):v;}\nI inner_moment(const Poly& a,const Poly& b,const Moments& v){\n I out=exact(0);\n for(const Term& x:a)for(const Term& y:b){Coeff c=conjugate_product(x.c,y.c);int k=x.k+y.k,m=y.m-x.m;accum(out,sub(mul(c.re,moment(v,k,m,0)),mul(c.im,moment(v,k,m,1))));}\n return out;\n}\nstruct PriceGenerator {\n double center=0,scale=1,step=.02,limit=8,ell=0,beta=0,invroot2=0;\n int rank=0;\n std::array<double,12> mean{};\n std::vector<double> factor;\n void read(I e,I b,I s){\n  center=read_double();scale=read_double();step=read_double();limit=read_double();\n  if(!(std::cin>>rank) || rank<0 || rank>12 || !(center>=0 && scale>0 && step>0 && limit>0))\n   throw std::runtime_error("Invalid generated-price parameters.");\n  ell=.5*e.lo+.5*e.hi;beta=.5*b.lo+.5*b.hi;invroot2=.5*s.lo+.5*s.hi;\n  for(double &x:mean)x=read_double();\n  factor.resize(12*rank);for(double &x:factor)x=read_double();\n }\n std::pair<double,double> weights(int ir,int it,int nr,int nt)const{\n  if(ir==nr-1)return {1e6,1e6};\n  // These unverified transcendental calculations merely CHOOSE positive\n  // dyadic weights. Every resulting weight is subsequently used as an exact\n  // constant in the outward moment and rational Schur certificate.\n  const double left=std::min(ir*step,limit),right=std::min((ir+1)*step,limit);\n  const double r=.5*left+.5*right,theta=(2*std::acos(-1.0))*((it+.5)/nt),u=r*r;\n  using C=std::complex<double>;const C z(r*std::cos(theta),r*std::sin(theta)),ii(0,1);\n  const C z2=z*z*invroot2,h=z*(u-2)*invroot2;\n  const std::array<C,12> f={C(1),C(u-1),z2,ii,ii*(u-1),-ii*z2,z,h,ii*z,ii*h,std::conj(z),ii*std::conj(z)};\n  C q(center),l=z*(ell+beta*(u-2));\n  for(int i=0;i<12;++i)q+=mean[i]*f[i];\n  double variance=0;\n  for(int j=0;j<rank;++j){C v(0);for(int i=0;i<12;++i)v+=factor[i*rank+j]*f[i];variance+=std::norm(v);}\n  const double wp=scale*std::max(1e-6,std::sqrt(std::max(0.0,std::norm(q+l)+variance)));\n  const double wm=scale*std::max(1e-6,std::sqrt(std::max(0.0,std::norm(q-l)+variance)));\n  if(!(wp>0 && wm>0 && std::isfinite(wp) && std::isfinite(wm)))throw std::runtime_error("Nonfinite generated weight.");\n  return {wp,wm};\n }\n};\nint main(int argc,char**argv){try{\n bool generated=false;\n if(argc==2 && std::string(argv[1])=="--generate")generated=true;\n else if(argc!=1)throw std::runtime_error("Usage: assemble_fiber [--generate]");\n\n platform_guard();\n int nr,nt;if(!(std::cin>>nr>>nt)||nr<1||nt<1||nr>20000||nt>20000)throw std::runtime_error("invalid cell counts");\n I ell=read_I(),beta=read_I(),invroot2=read_I();\n if(ell.lo<0||beta.lo<0||invroot2.lo<=0)throw std::runtime_error("invalid polynomial parameters");\n std::vector<std::array<I,7>> radial(nr);for(auto &r:radial)for(I &v:r)v=read_I();\n std::vector<Angular> angular(nt);for(auto &r:angular)for(auto &v:r)for(I &x:v)x=read_I();\n PriceGenerator generator;if(generated)generator.read(ell,beta,invroot2);\n Moments plus{},minus{};I w_mass=exact(0),prob_mass=exact(0);\n for(int ir=0;ir<nr;++ir){\n  Angular ap{},am{};I aw=exact(0);\n  for(int it=0;it<nt;++it){\n   double wp,wm;\n   if(generated){const auto w=generator.weights(ir,it,nr,nt);wp=w.first;wm=w.second;}\n   else {wp=read_double();wm=read_double();}\n   if(!(wp>0&&wm>0))throw std::runtime_error("step weights must be positive");\n   I ip=recip_positive(exact(wp)),im=recip_positive(exact(wm));\n   I s=mul(exact(.5),add(ip,im)),d=mul(exact(.5),sub(ip,im)),w=mul(exact(.5),add(exact(wp),exact(wm)));\n   for(int m=0;m<=4;++m)for(int cs=0;cs<2;++cs){accum(ap[m][cs],mul(s,angular[it][m][cs]));accum(am[m][cs],mul(d,angular[it][m][cs]));}\n   accum(aw,mul(w,angular[it][0][0]));\n   accum(prob_mass,mul(radial[ir][0],angular[it][0][0]));\n  }\n  accum(w_mass,mul(radial[ir][0],aw));\n  for(int k=0;k<=6;++k)for(int m=0;m<=4;++m)for(int cs=0;cs<2;++cs){accum(plus[k][m][cs],mul(radial[ir][k],ap[m][cs]));accum(minus[k][m][cs],mul(radial[ir][k],am[m][cs]));}\n }\n std::string extra;if(std::cin>>extra)throw std::runtime_error("unexpected trailing input");\n I one=exact(1),mone=exact(-1),n2s=mul(exact(-2),invroot2);\n std::array<Poly,12> B;\n B[0]={{0,0,realcoef(one)}};\n B[1]={{2,0,realcoef(one)},{0,0,realcoef(mone)}};\n B[2]={{2,2,realcoef(invroot2)}};\n B[3]={{0,0,imagcoef(one)}};\n B[4]={{2,0,imagcoef(one)},{0,0,imagcoef(mone)}};\n B[5]={{2,2,imagcoef(neg(invroot2))}};\n B[6]={{1,1,realcoef(one)}};\n B[7]={{3,1,realcoef(invroot2)},{1,1,realcoef(n2s)}};\n B[8]={{1,1,imagcoef(one)}};\n B[9]={{3,1,imagcoef(invroot2)},{1,1,imagcoef(n2s)}};\n B[10]={{1,-1,realcoef(one)}};\n B[11]={{1,-1,imagcoef(one)}};\n Poly L={{1,1,realcoef(sub(ell,mul(exact(2),beta)))},{3,1,realcoef(beta)}};\n std::array<std::array<I,12>,12> G;std::array<I,12>b;\n for(int i=0;i<12;++i){b[i]=inner_moment(B[i],L,minus);for(int j=i;j<12;++j)G[j][i]=G[i][j]=inner_moment(B[i],B[j],plus);}\n I c=add(w_mass,inner_moment(L,L,plus));\n std::cout<<"{\\"G\\":[";\n for(int i=0;i<12;++i){if(i)std::cout<<\',\';std::cout<<\'[\';for(int j=0;j<12;++j){if(j)std::cout<<\',\';print_I(G[i][j]);}std::cout<<\']\';}\n std::cout<<"],\\"b\\":[";for(int i=0;i<12;++i){if(i)std::cout<<\',\';print_I(b[i]);}\n std::cout<<"],\\"c\\":";print_I(c);std::cout<<",\\"w_mass\\":";print_I(w_mass);std::cout<<",\\"prob_mass\\":";print_I(prob_mass);std::cout<<"}\\n";\n return 0;\n}catch(const std::exception&e){std::cerr<<"assembly error: "<<e.what()<<\'\\n\';return 1;}}\n'

