EPS=F(37,50)
RHO=F(49,50)
CUBIC_SIXTH=F(50)
X_MAX=F(31,4)
T_MAX=F(9,10)
N_TARGET=F(2857,4000)

def verify_elementary_constants():
    # The symbolic gate proves the tensor identities; these check auxiliary constants.
    assert 68**2-3517==1107 and 68**2-2094==2530
    assert 1107*2530-640**2*6==343110>0
    assert F(27,50)*68**2<50**2
    p=[F(4),F(0),F(65,2),F(-175,3),F(25)]
    a=multiply([F(-1,10),F(-7,6),F(1)],[F(-1,10),F(-7,6),F(1)])
    b=multiply([F(-21,25),F(1)],[F(-21,25),F(1)])
    rhs=[25*v for v in a]
    for i,v in enumerate(b):rhs[i]+=F(125,36)*v
    rhs[0]+=F(13,10)
    assert p==rhs and (1296+1944)*F(1,36)==90
    assert 2+F(2,3)*90==62 and X_MAX**2>60
    assert NUHI<T_MAX and N_TARGET<F(5,7)

def profile_gate(p):
    assert F(p['epsilon'])==EPS and 0<F(p['delta'])<EPS
    assert p['M_R']==p['M_I'] and F(p['ell'])>=2*F(p['beta'])>=0
    delta=F(p['delta'])
    for name,ds in [('M_E',[[-1,EPS,EPS],[EPS-delta,0,0]]),
                    ('M_R',[[-1,EPS],[EPS,0]])]:
        a=[list(map(F,row)) for row in p[name]]
        exact_positive_definite(a,p['id']+' '+name)
        for diagonal in ds:
            b=[[v-(F(diagonal[i]) if i==j else 0) for j,v in enumerate(row)] for i,row in enumerate(a)]
            exact_positive_definite(b,p['id']+' '+name+' dominance',strict=False)

def moment_text(data):
    lines=[' '.join(x for pair in row for x in interval_hex(pair)) for row in data['radial']]
    for cs,ss in zip(data['cosine'],data['sine']):
        lines.append(' '.join(x for cp,sp in zip(cs,ss) for pair in (cp,sp) for x in interval_hex(pair)))
    return '\n'.join(lines)+'\n'

def choice_hex(x):
    x=float(x);assert math.isfinite(x)
    return x.hex()

def price_input(profile,pool,recipe,data,text):
    mean,factor=recipe['mean'],recipe['factor'];assert len(mean)==len(factor)==12
    rank=len(factor[0]);assert 0<=rank<=12 and all(len(row)==rank for row in factor)
    assert F(pool['tail_w'])==1000000 and F(recipe['scalar_center'])>=0 and float(recipe['w_scale'])>0
    header=interval_hex(pt(F(profile['ell'])))+interval_hex(pt(F(profile['beta'])))+interval_hex(data['invsqrt2'])
    out=f"{len(data['radial'])} {len(data['cosine'])}\n"+' '.join(header)+'\n'+text
    out+=' '.join([choice_hex(recipe['scalar_center']),choice_hex(recipe['w_scale']),choice_hex(pool['radial_step']),choice_hex(pool['radial_end']),str(rank)])+'\n'
    out+=' '.join(map(choice_hex,mean))+'\n'+' '.join(choice_hex(x) for row in factor for x in row)+'\n'
    return out

def replay_price(profile,pool,recipe,data,text,program):
    process=subprocess.run([str(program),'--generate'],input=price_input(profile,pool,recipe,data,text),text=True,capture_output=True)
    if process.returncode:raise RuntimeError(profile['id']+' '+recipe['name']+': '+process.stderr)
    moments=json.loads(process.stdout);mass=fromhex(moments['prob_mass']);assert mass[0]<=1<=mass[1]
    return list(map(F,reduce_residual(profile,moments)['upper_coefficients']))

def contiguous(cells,stop):
    cells=sorted(cells,key=lambda c:F(c[0]));assert cells
    assert F(cells[0][0])==0 and F(cells[-1][1])==F(stop)
    assert all(F(c[0])<F(c[1]) for c in cells)
    assert all(F(a[1])==F(b[0]) for a,b in zip(cells,cells[1:]))
    return cells

def make_supports(group,quadratics):
    points=[]
    for point in group['points']:
        r=F(point['r']);i=point['recipe'];assert 0<=i<len(quadratics) and r>=0
        cap=F(point['cap']);assert value(quadratics[i],r)<=cap
        points.append((r,cap))
    assert points and points[0][0]==0 and all(a[0]<b[0] for a,b in zip(points,points[1:]))
    supports=[]
    for a,b in zip(points,points[1:]):
        slope=(b[1]-a[1])/(b[0]-a[0])
        supports.append({'coefficients':[a[1]-slope*a[0],slope],'lo':a[0],'hi':b[0]})
    r,cap=points[-1];supports.append({'coefficients':[cap-2*r,F(2)],'lo':r,'hi':None})
    return supports

def verify_physical_polynomial(polynomial,supports):
    p=list(map(F,polynomial['coefficients']))
    assert len(p)==7 and p[1]>=0 and p[6]>=0 and p[3]==p[5]==0
    proof=polynomial['physical'];tail=F(proof['tail_start'])
    for L,H,index in contiguous(proof['cells'],tail):
        L,H=F(L),F(H);assert 0<=index<len(supports);s=supports[index]
        assert L>=s['lo'] and (s['hi'] is None or H<=s['hi'])
        assert min(bernstein(difference(p,s['coefficients']),L,H))>=0
    index=proof['tail_index'];assert 0<=index<len(supports);s=supports[index]
    assert s['hi'] is None and tail>=s['lo']
    assert min(shifted(difference(p,s['coefficients']),tail))>=0
    return p

def moment_box_upper(p,delta,box):
    L,H,A,B=map(F,box);assert 0<=L<H and 0<=A<B
    # For fixed sigma the x part is a*x^2+b*x^3, b>=0.
    # Its positive stationary point, if any, is a minimum.
    def coefficients(x):
        return [p[0],RHO*p[1],p[2]-1/delta,F(0),p[4]*(2+x*x),F(0),p[6]*(6+9*x*x+50*x*x*x)]
    return max(max(bernstein(coefficients(x),L,H)) for x in (A,B))

def verify_rectangles(group,polynomials):
    delta=F(group['profile']['delta']);S=F(group['sigma_max']);X=F(group['x_max']);cap=F(group['C_cap'])
    assert S>=delta*RHO and X>=X_MAX
    boxes=[]
    for row in group['rectangles']:
        assert 'modulus_nodes' not in row and not row.get('absolute_sixth',False)
        box=tuple(map(F,row['box']));L,H,A,B=box
        assert 0<=L<H<=S and 0<=A<B<=X
        index=row['polynomial'];assert 0<=index<len(polynomials)
        upper=moment_box_upper(polynomials[index],delta,box)
        assert upper<=cap,(group['profile']['id'],box,upper,cap)
        boxes.append(box)
    assert boxes
    edges=sorted({z for box in boxes for z in box[:2]});assert edges[0]==0 and edges[-1]==S
    for L,H in zip(edges,edges[1:]):
        mid=(L+H)/2;spans=sorted((A,B) for a,b,A,B in boxes if a<=mid<b)
        assert spans and spans[0][0]==0 and spans[-1][1]==X
        assert all(a[1]==b[0] for a,b in zip(spans,spans[1:])),('Rectangle gap or overlap',L,H)

def verify_final_intervals(groups):
    profiles=[dict(id='crude',ell='0',C_cap=str(EPS*RHO**2))]
    profiles += [dict(id=g['profile']['id'],ell=g['profile']['ell'],C_cap=g['C_cap']) for g in groups]
    profiles.sort(key=lambda p:F(p['ell']))
    assert all(F(a['ell'])<F(b['ell']) for a,b in zip(profiles,profiles[1:]))
    endpoints=[F(0)]
    for a,b in zip(profiles,profiles[1:]):
        endpoints.append((F(b['C_cap'])-F(a['C_cap']))/(2*(F(b['ell'])-F(a['ell']))))
    endpoints.append(T_MAX)
    assert all(a<b for a,b in zip(endpoints,endpoints[1:]))
    intervals=[]
    for p,L,H in zip(profiles,endpoints,endpoints[1:]):
        upper=max(t*t-2*F(p['ell'])*t+F(p['C_cap']) for t in (L,H))
        assert upper<N_TARGET,(p['id'],L,H,upper)
        intervals.append(dict(id=p['id'],left=str(L),right=str(H),upper=str(upper)))
    return max(F(r['upper']) for r in intervals),intervals


# Exact symbolic Wick and scalar checks, embedded for standalone use.
CUBIC_ALGEBRA_SOURCE = '#!/usr/bin/env python3\n"""Exact, dimension-independent checks for the cubic-chaos moment lemma.\n\nRun with Python 3; only the standard library is used. All coefficients are\nfractions of integers. No floating-point arithmetic or sample tensors occur.\n\nA product of entries of a symmetric real tensor f_{abc}, with each summed\nindex occurring twice, is encoded by a multigraph: tensor factors are vertices\nand summed indices are edges. Vertex permutation and dummy-index renaming do\nnot change the contraction. We compare exact linear combinations after\ncanonicalizing graphs under every vertex permutation. Consequently each\nchecked equality holds for EVERY symmetric real tensor in EVERY finite\ndimension. Graphs need not be linearly independent: equality of the formal\nsums is sufficient.\n\nFor I_3(f), Wick\'s rule gives the coefficient (3!)^v/prod(e_ij!) for a\nloopless cubic multigraph on v labelled vertices. The moment-cumulant formula\nretains precisely the connected graphs. The enumeration below tries every\npermitted edge multiplicity, with the remaining degrees tracking all three\nlegs at every vertex; hence it omits no Wick diagram.\n\nDefinitions (repeated indices are summed; all norms are Hilbert--Schmidt):\n  F_ab,c=f_abc; G=F^T F; C=F F^T;\n  S_abcd=(C_abcd+C_acbd+C_adbc)/3;\n  D=F G; U=S F; s=||G||^2; h=||S||^2;\n  V=||D||^2; B0=||F^T vec(G)||^2;\n  A0=sum f_abc f_dec G_ad G_be.\nIf G is diagonal, A0=sum lambda_a lambda_b f_abc^2.\n\nIn addition to the two Wick identities, this checks a polynomial inequality\non [0,1] by rational Bernstein coefficients, and a sum-of-squares identity\nused for the first absolute moment. It is independent of the Gaussian\nintegration verifier check_complex_lower.py.\n"""\nfrom collections import Counter\nfrom fractions import Fraction as Q\nfrom functools import lru_cache\nfrom itertools import permutations\nfrom math import comb, factorial\n\n\n@lru_cache(None)\ndef pairs(n):\n    return tuple((i, j) for i in range(n) for j in range(i + 1, n))\n\n\n@lru_cache(None)\ndef permutation_actions(n):\n    edges = pairs(n)\n    positions = {edge: k for k, edge in enumerate(edges)}\n    return tuple(tuple(positions[tuple(sorted((p[i], p[j])))]\n                       for i, j in edges) for p in permutations(range(n)))\n\n\ncanonical_cache = {}\n\n\ndef canonical(graph, n):\n    """Lexicographically least encoding under ALL n! vertex permutations."""\n    cache = canonical_cache.setdefault(n, {})\n    if graph not in cache:\n        orbit = {tuple(graph[k] for k in action)\n                 for action in permutation_actions(n)}\n        representative = min(orbit)\n        cache.update((g, representative) for g in orbit)\n    return cache[graph]\n\n\ndef connected(graph, n):\n    reached = {0}\n    while True:\n        expanded = reached.copy()\n        for multiplicity, (i, j) in zip(graph, pairs(n)):\n            if multiplicity and (i in reached or j in reached):\n                expanded.update((i, j))\n        if expanded == reached:\n            return len(reached) == n\n        reached = expanded\n\n\ndef cubic_graphs(n):\n    """Exhaust all labelled loopless graphs with every degree exactly three."""\n    edges = pairs(n)\n    graph = [0] * len(edges)\n    degree = [3] * n\n\n    def visit(k):\n        if k == len(edges):\n            if not any(degree):\n                yield tuple(graph)\n            return\n        i, j = edges[k]\n        for multiplicity in range(min(degree[i], degree[j]) + 1):\n            graph[k] = multiplicity\n            degree[i] -= multiplicity\n            degree[j] -= multiplicity\n            # No later edge can use i after the last edge of its row.\n            if j != n - 1 or degree[i] == 0:\n                yield from visit(k + 1)\n            degree[i] += multiplicity\n            degree[j] += multiplicity\n    yield from visit(0)\n\n\ndef wick_cumulant(n):\n    result = Counter()\n    labelled_count = 0\n    for graph in cubic_graphs(n):\n        if connected(graph, n):\n            labelled_count += 1\n            weight = Q(factorial(3) ** n)\n            for multiplicity in graph:\n                weight /= factorial(multiplicity)\n            result[canonical(graph, n)] += weight\n    return result, labelled_count\n\n\n# A tensor expression is a list of (rational coefficient, tensor-factor list).\n# Each tensor factor is a triple of symbolic indices. Internal indices are\n# fresh objects, so different recursive expansions cannot accidentally share\n# a dummy index. Multiplying expressions forms the ordinary Cartesian product.\ndef product(*expressions):\n    terms = [(Q(1), [])]\n    for expression in expressions:\n        terms = [(a * b, u + v) for a, u in terms for b, v in expression]\n    return terms\n\n\ndef scaled(expression, coefficient):\n    return [(coefficient * a, u) for a, u in expression]\n\n\ndef tensor(name, *i):\n    if name == \'f\':\n        assert len(i) == 3\n        return [(Q(1), [i])]\n    if name == \'G\':\n        assert len(i) == 2\n        a, b = object(), object()\n        return product(tensor(\'f\', a, b, i[0]), tensor(\'f\', a, b, i[1]))\n    if name == \'C\':\n        assert len(i) == 4\n        a = object()\n        return product(tensor(\'f\', i[0], i[1], a),\n                       tensor(\'f\', i[2], i[3], a))\n    if name == \'S\':\n        assert len(i) == 4\n        a, b, c, d = i\n        return scaled(tensor(\'C\', a, b, c, d) + tensor(\'C\', a, c, b, d)\n                      + tensor(\'C\', a, d, b, c), Q(1, 3))\n    if name == \'D\':\n        assert len(i) == 3\n        a = object()\n        return product(tensor(\'f\', i[0], i[1], a), tensor(\'G\', a, i[2]))\n    if name == \'U\':\n        assert len(i) == 3\n        a, b = object(), object()\n        return product(tensor(\'S\', i[0], i[1], a, b),\n                       tensor(\'f\', a, b, i[2]))\n    if name == \'b\':\n        assert len(i) == 1\n        a, b = object(), object()\n        return product(tensor(\'f\', a, b, i[0]), tensor(\'G\', a, b))\n    raise ValueError(name)\n\n\ndef inner(name, other, rank):\n    i = tuple(object() for _ in range(rank))\n    return product(tensor(name, *i), tensor(other, *i))\n\n\ndef contraction_sum(expression):\n    """Convert closed tensor products to exact canonical multigraph sums."""\n    result = Counter()\n    for coefficient, factors in expression:\n        n = len(factors)\n        occurrences = {}\n        for vertex, factor in enumerate(factors):\n            for index in factor:\n                occurrences.setdefault(index, []).append(vertex)\n        graph = Counter()\n        for endpoints in occurrences.values():\n            assert len(endpoints) == 2, \'Every index must be contracted twice\'\n            a, b = sorted(endpoints)\n            assert a != b, \'No contraction internal to a Wick tensor\'\n            graph[a, b] += 1\n        encoding = tuple(graph[edge] for edge in pairs(n))\n        assert all(sum(m for edge, m in graph.items() if i in edge) == 3\n                   for i in range(n))\n        result[canonical(encoding, n)] += coefficient\n    return {g: a for g, a in result.items() if a}\n\n\n# Minimal exact polynomial arithmetic: coefficients are in ascending order.\ndef add(*polynomials):\n    out = [Q(0)] * max(map(len, polynomials))\n    for p in polynomials:\n        for i, a in enumerate(p):\n            out[i] += a\n    return out\n\n\ndef scale(p, a):\n    return [a * x for x in p]\n\n\ndef mul(p, q):\n    out = [Q(0)] * (len(p) + len(q) - 1)\n    for i, a in enumerate(p):\n        for j, b in enumerate(q):\n            out[i + j] += a * b\n    return out\n\n\ndef power(p, n):\n    out = [Q(1)]\n    for _ in range(n):\n        out = mul(out, p)\n    return out\n\n\ndef on_interval(p, lo, hi):\n    """Coefficients after x = lo + (hi-lo)t, 0<=t<=1."""\n    out = [Q(0)] * len(p)\n    for j, a in enumerate(p):\n        for k in range(j + 1):\n            out[k] += a * comb(j, k) * lo ** (j - k) * (hi - lo) ** k\n    return out\n\n\ndef bernstein(p):\n    n = len(p) - 1\n    return [sum((p[j] * Q(comb(k, j), comb(n, j))\n                 for j in range(k + 1)), Q(0)) for k in range(n + 1)]\n\n\ndef positive_on_unit_interval(p):\n    """All-positive Bernstein coefficients certify positivity on each leaf.\n\n    Subdivision replaces [a,b] by its two closed halves, so accepted leaves\n    cover [0,1], including endpoints. The depth cap is only a failure guard.\n    """\n    todo = [(Q(0), Q(1), 0)]\n    leaves = []\n    while todo:\n        lo, hi, depth = todo.pop()\n        coefficients = bernstein(on_interval(p, lo, hi))\n        if min(coefficients) > 0:\n            leaves.append((lo, hi, min(coefficients)))\n        else:\n            assert depth < 20, \'Unable to certify polynomial positivity\'\n            mid = (lo + hi) / 2\n            todo.extend([(lo, mid, depth + 1), (mid, hi, depth + 1)])\n    return leaves\n\n\ndef verify_cubic_algebra():\n    if not __debug__:\n        raise RuntimeError("Run this verifier without Python assertion suppression (-O).")\n    k4, count4 = wick_cumulant(4)\n    rhs4 = scaled(inner(\'G\', \'G\', 2), Q(1296))\n    rhs4 += scaled(inner(\'S\', \'S\', 4), Q(1944))\n    assert dict(k4) == contraction_sum(rhs4)\n    print(f\'FOURTH_CUMULANT_IDENTITY=PASS labelled_graphs={count4} \'\n          f\'graph_classes={len(k4)}\')\n\n    a, b, c, d, e, f = (object() for _ in range(6))\n    trace_s3 = product(tensor(\'S\', a, b, c, d),\n                       tensor(\'S\', c, d, e, f), tensor(\'S\', e, f, a, b))\n    a0 = product(tensor(\'f\', a, b, c), tensor(\'f\', d, e, c),\n                 tensor(\'G\', a, d), tensor(\'G\', b, e))\n    v = inner(\'D\', \'D\', 3)\n    b0 = inner(\'b\', \'b\', 1)\n    du = inner(\'D\', \'U\', 3)\n    u2 = inner(\'U\', \'U\', 3)\n    # Keep the two V terms separate to match the stated aggregate identity.\n    rhs6 = scaled(trace_s3, Q(135, 2)) + scaled(v, Q(25))\n    rhs6 += scaled(b0, Q(45, 2)) + scaled(du, Q(165, 2))\n    rhs6 += scaled(u2, Q(45)) + scaled(a0, Q(45)) + scaled(v, Q(-45))\n    k6, count6 = wick_cumulant(6)\n    assert {g: a / 46656 for g, a in k6.items()} == contraction_sum(rhs6)\n    print(f\'SIXTH_CUMULANT_IDENTITY=PASS labelled_graphs={count6} \'\n          f\'graph_classes={len(k6)}\')\n\n    numerator = [Q(95, 2), Q(165, 2), Q(45), Q(135, 2)]\n    denominator_squared = power([Q(1), Q(0), Q(3, 2)], 3)\n    gap = add(scale(denominator_squared, Q(68 ** 2)),\n              scale(mul(numerator, numerator), Q(-1)))\n    leaves = positive_on_unit_interval(gap)\n    assert all(a >= 0 for a in numerator)\n    print(f\'CUMULANT_RATIO_LT_68=PASS bernstein_intervals={len(leaves)} \'\n          f\'minimum_coefficient={min(v for _, _, v in leaves)}\')\n    assert 68 ** 2 * 54 < 50 ** 2 * 100\n    print(\'COMPLEX_SIXTH_MOMENT_COEFFICIENT_LT_50=PASS\')\n\n    # m=x^2+2 and n6<=9m-12+50x^3 imply that the target expression\n    # 25(m-1)^2-7*n6/6-7*m is at least the following quartic.\n    m = [Q(2), Q(0), Q(1)]\n    n6_upper = add(scale(m, Q(9)), [Q(-12), Q(0), Q(0), Q(50)])\n    quartic = add(scale(power(add(m, [Q(-1)]), 2), Q(25)),\n                  scale(n6_upper, Q(-7, 6)), scale(m, Q(-7)))\n    sos = add(scale(power([Q(-1, 10), Q(-7, 6), Q(1)], 2), Q(25)),\n              scale(power([Q(-21, 25), Q(1)], 2), Q(125, 36)), [Q(13, 10)])\n    assert quartic == sos\n    print(\'FIRST_ABSOLUTE_MOMENT_SUM_OF_SQUARES=PASS\')\n    print(\'ALL_CUBIC_ALGEBRA_CHECKS=PASS\')\n\n\nif __name__ == \'__main__\':\n    verify_cubic_algebra()\n'

def verify_symbolic_cubic_algebra():
    namespace={"__name__":"cubic_algebra_embedded"}
    exec(compile(CUBIC_ALGEBRA_SOURCE,"check_cubic_algebra.py","exec"),namespace)
    namespace["verify_cubic_algebra"]()

def main():
    from concurrent.futures import ThreadPoolExecutor
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--workers',type=int,choices=range(1,5),default=min(4,os.cpu_count() or 1))
    args=parser.parse_args()
    if not __debug__:raise RuntimeError('Run without -O; assertions are proof gates.')
    assert sys.float_info.radix==2 and sys.float_info.mant_dig==53 and sys.float_info.max_exp==1024
    assert shutil.which('g++'),'g++ with C++17 support is required.'
    started=time.time();verify_symbolic_cubic_algebra();verify_elementary_constants()
    print('PASS elementary cubic constants and sum-of-squares identity',flush=True)
    grids={};texts={};counts=[0,0,0]
    with tempfile.TemporaryDirectory(prefix='kg_simple_certificate_') as folder:
        folder=Path(folder);path=folder/'residual.cpp';path.write_text(CPP_RESIDUAL);program=folder/'residual'
        subprocess.run(['g++','-O3','-std=c++17','-fno-fast-math','-ffp-contract=off',str(path),'-o',str(program)],check=True,capture_output=True,text=True)
        with ThreadPoolExecutor(max_workers=args.workers) as executor:
            for group in DATA:
                assert group['kind']=='residual_chord'
                p=group['profile'];profile_gate(p);print('PASS profile matrices',p['id'],flush=True)
                tasks=[]
                for pool in group['pools']:
                    key=(pool['radial_step'],pool['theta_cells'],pool['radial_end'])
                    if key not in grids:
                        data=generate(F(key[0]),int(key[1]),F(key[2]));grids[key]=data;texts[key]=moment_text(data)
                        print('PASS Gaussian moments with tail:',len(data['radial']),'radial rows;',len(data['cosine']),'angles',flush=True)
                    for recipe in pool['prices']:tasks.append((pool,recipe,grids[key],texts[key]))
                def worker(task):return replay_price(p,*task,program)
                qs=[]
                for i,q in enumerate(executor.map(worker,tasks),1):
                    qs.append(q)
                    if i%25==0 or i==len(tasks):print('  PASS price/Schur',i,'/',len(tasks),flush=True)
                supports=make_supports(group,qs)
                polynomials=[verify_physical_polynomial(poly,supports) for poly in group['polynomials']]
                verify_rectangles(group,polynomials)
                print('PASS global polynomials and moment rectangles; C =',group['C_cap'],flush=True)
                counts=[a+b for a,b in zip(counts,[len(qs),len(polynomials),len(group['rectangles'])])]
    bound,intervals=verify_final_intervals(DATA)
    print('PASS full t range [0,9/10]:',len(intervals),'rational intervals')
    print('Exact norm upper:',bound)
    print('Norm upper decimal: %.15f'%float(bound))
    print('Certified lower bound: K_G^C > 4000/2857 > 7/5')
    print('CERTIFICATE PASSED;',len(DATA),'profiles;',counts[0],'prices;',counts[1],'polynomials;',counts[2],'rectangles; elapsed %.1fs'%(time.time()-started))

if __name__=='__main__':main()
